// Phase 1.4 metric registry — one entry per real, imported report exhibit
// (see content/report-crosswalk.csv, the source this file is generated
// from). `definition`/`population`/`geographicLevel` are deliberately left
// as TBD markers, not guessed — they need a human pass against the
// report's own defining language, per Phase 1.3's "do not repair
// substantive inconsistencies without author review." Everything else
// (source, years, format function, related report item) is real, read
// directly from public/data/talent.json and the crosswalk.
//
// Chart components should read titles/units/source labels/number formats
// from here where practical (Phase 1.4's own requirement) rather than
// hardcoding them per component.

export type FormatFn = (n: number) => string;

export const formatCount: FormatFn = (n) => Math.round(n).toLocaleString();
export const formatPercent: FormatFn = (n) => `${n.toFixed(1)}%`;
export const formatUsd: FormatFn = (n) => {
  if (n >= 1e9) return `$${(n / 1e9).toFixed(1)}B`;
  if (n >= 1e6) return `$${(n / 1e6).toFixed(1)}M`;
  return `$${Math.round(n).toLocaleString()}`;
};

export interface MetricEntry {
  id: string;
  displayName: string;
  shortLabel: string;
  definition: string;
  unit: string;
  formatFn: FormatFn;
  source: string;
  sourceUrl: string;
  firstYear: number | null;
  latestYear: number | null;
  updateFrequency: string;
  geographicLevel: string;
  population: string;
  caveats: string;
  relatedReportItem: string;
  recommendedChartForms: string;
  stage: string;
}

